import{_ as e,o as d,c as o,a2 as a}from"./chunks/framework.CeXt7FPx.js";const p=JSON.parse('{"title":"Files and ports","description":"","frontmatter":{},"headers":[],"relativePath":"reference/files.md","filePath":"reference/files.md"}'),i={name:"reference/files.md"};function s(c,t,r,n,f,l){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="files-and-ports" tabindex="-1">Files and ports <a class="header-anchor" href="#files-and-ports" aria-label="Permalink to &quot;Files and ports&quot;">​</a></h1><h2 id="folders" tabindex="-1">Folders <a class="header-anchor" href="#folders" aria-label="Permalink to &quot;Folders&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>macOS</th><th>Windows</th><th>Linux</th></tr></thead><tbody><tr><td>Data: runtimes, databases, mail, CA</td><td><code>~/Library/Application Support/Tiffin</code></td><td><code>%LOCALAPPDATA%\\Tiffin</code></td><td><code>~/.local/share/tiffin</code></td></tr><tr><td>Settings</td><td>the same</td><td>the same</td><td><code>~/.config/tiffin</code></td></tr><tr><td>tiffind&#39;s own state and database</td><td>the same</td><td>the same</td><td><code>~/.local/state/tiffin</code></td></tr><tr><td>Logs</td><td><code>~/Library/Logs/Tiffin</code></td><td><code>%LOCALAPPDATA%\\Tiffin\\logs</code></td><td><code>~/.local/state/tiffin/logs</code></td></tr><tr><td>Downloads cache</td><td><code>~/Library/Caches/Tiffin</code></td><td><code>%LOCALAPPDATA%\\Tiffin\\cache</code></td><td><code>~/.cache/tiffin</code></td></tr><tr><td>Shims (on your PATH)</td><td><code>~/.tiffin/shims</code></td><td><code>%LOCALAPPDATA%\\Tiffin\\shims</code></td><td><code>~/.local/share/tiffin/shims</code></td></tr><tr><td>The programs</td><td><code>Tiffin.app/Contents/MacOS</code></td><td><code>%LOCALAPPDATA%\\Programs\\Tiffin</code></td><td><code>/usr/lib/tiffin</code></td></tr></tbody></table><p>On Linux the folders follow <code>XDG_DATA_HOME</code>, <code>XDG_CONFIG_HOME</code>, <code>XDG_STATE_HOME</code> and <code>XDG_CACHE_HOME</code> when set. <code>TIFFIN_HOME</code> puts everything in one folder instead.</p><p>Inside the data folder, <code>tools/</code> holds installed packages, <code>services/</code> the databases&#39; data, <code>mail/</code> caught mail and <code>ca/</code> Tiffin&#39;s certificate authority. <code>tiffin db backup</code> writes to <code>backups/</code>.</p><h2 id="ports" tabindex="-1">Ports <a class="header-anchor" href="#ports" aria-label="Permalink to &quot;Ports&quot;">​</a></h2><p>All of them on loopback only (<code>127.0.0.1</code>, <code>::1</code>); nothing listens on your network unless you share a site with <code>tiffin share --lan</code>.</p><table tabindex="0"><thead><tr><th>Port</th><th>What</th></tr></thead><tbody><tr><td>80, 443 (else 8080, 8443)</td><td>your sites, HTTP and HTTPS</td></tr><tr><td>53 on <code>127.0.53.1</code> (Windows, Linux), 1053 (macOS)</td><td><code>.test</code> names</td></tr><tr><td>2525</td><td>caught mail (SMTP)</td></tr><tr><td>9913</td><td>dumps and queries from the Laravel package</td></tr><tr><td>each service&#39;s own</td><td>databases and caches: <code>tiffin service list</code></td></tr></tbody></table><p><code>.test</code> names, mail and dumps move with <code>tiffin config set</code> or the app&#39;s <strong>Settings &gt; Ports</strong> (saved in <code>settings.json</code> in the settings folder); any of them with <a href="/tiffin/reference/environment">Environment variables</a>, which win over a saved address.</p>',9)])])}const m=e(i,[["render",s]]);export{p as __pageData,m as default};
